function ex_assert($v,$m='Assertion failed'){if(!$v)throw new RuntimeException($m);}
function ex_case($name,$fn){global $tests,$failures;$tests++;try{$fn();echo 'PASS '.$name."\n";}catch(Throwable $e){$failures++;echo 'FAIL '.$name.': '.$e->getMessage().' '.$e->getFile().':'.$e->getLine()."\n";}}
function ex_reject($fn,$code){try{$fn();}catch(Throwable $e){ex_assert(strpos($e->getMessage(),$code)!==false,'Wrong failure '.$e->getMessage());return;}throw new RuntimeException('Expected '.$code);}
