ex_case('Simulation consumes published-access and review message fields without adding a different participant flow',function(){global $svc,$nativeDefinition;$x=ex_fixture('IMMEDIATE');$d=$x['definition'];$d['protocol_metadata']['public_messages']=array('email_first_link'=>'Ingreso personalizado','email_verified'=>'Validación personalizada');$x=$svc->save($x['id'],$x['revision'],'CUSTOM_ACCESS_MESSAGES',$d);$r=ex_run($x,array(ex_cmd('ENTER')));ex_assert($r['notice']==='Ingreso personalizado'&&$r['verification_required']&&$r['assessment']===null,'Ingreso: '.json_encode(array($r['notice'],$r['verification_required'],$r['assessment']!==null)));$r=ex_run($x,array(ex_cmd('ENTER'),ex_cmd('EMAIL',array('id'=>$r['emails'][0]['id']))));ex_assert($r['verified']&&$r['assessment']!==null&&$r['notice']==='Validación personalizada');$x=ex_fixture();$d=$x['definition'];$d['protocol_metadata']['public_messages']=array('review_title'=>'Confirmación personalizada','change_body'=>'Cambio personalizado');$initial=&$d['protocol_metadata']['longitudinal']['initial_screen'];$initial['title_html']='<h1>ENTRY_TITLE_ONLY</h1>';$initial['description_html']='<p>ENTRY_DESCRIPTION_ONLY</p>';$initial['footer_html']='<p>ENTRY_FOOTER_ONLY</p>';unset($initial);$x=$svc->save($x['id'],$x['revision'],'CUSTOM_REVIEW_MESSAGES',$d);$answers=array();foreach($nativeDefinition['elements'] as $q)$answers[$q['response_key']]='Respuesta';$r=ex_run($x,array(ex_cmd('ENTER'),ex_cmd('SUBMIT',array('answers'=>$answers,'touched'=>array()))));ex_assert($r['review']&&strpos($r['review_html'],'<h1>Confirmación personalizada</h1>')!==false&&strpos($r['review_html'],'Cambio personalizado')!==false);ex_assert(strpos($r['review_html'],'data-notice="review_title"')===false&&strpos($r['review_html'],'data-notice="review_body"')===false,'Review heading rendered as notice');foreach(array('ENTRY_TITLE_ONLY','ENTRY_DESCRIPTION_ONLY','ENTRY_FOOTER_ONLY','data-open-withdrawal','data-withdrawal-choice') as $forbidden)ex_assert(strpos($r['review_html'],$forbidden)===false,'Entry content leaked into review: '.$forbidden);ex_assert(strpos($r['initial_html'],'ENTRY_TITLE_ONLY')!==false,'Entry screen was changed');});
ex_case('Expired assessment email still verifies while security capability is valid',function()use(&$x){$r=ex_run($x,array(ex_cmd('ENTER'),ex_cmd('LEAVE'),ex_cmd('ADVANCE',array('seconds'=>10800)),ex_cmd('EMAIL',array('id'=>'MAIL_0'))));ex_assert($r['verified']&&$r['assessment']===null&&$r['notice']===EIPSI\StudyEngine\Runtime\PublicMessages::text($x['definition'],'email_expired_wait'));ex_assert(strpos($r['notice'],'siguiente evaluación disponible')===false);foreach(array('email_verified','assessment_expired','finished_body') as $key)ex_assert(substr_count($r['status_html'],'data-notice="'.$key.'"')===1,$key);ex_assert(strpos($r['status_html'],'eipsi-initial')!==false&&$r['notice_in_portal']);foreach(array('email_verified','wait_title','email_future_notices','next_time') as $key)ex_assert(strpos($r['landing_html'],'data-notice="'.$key.'"')===false,'Landing restores notice: '.$key);$repeat=ex_run($x,array(ex_cmd('ENTER'),ex_cmd('LEAVE'),ex_cmd('ADVANCE',array('seconds'=>10800)),ex_cmd('EMAIL',array('id'=>'MAIL_0')),ex_cmd('EMAIL',array('id'=>'MAIL_0'))));ex_assert(strpos($repeat['status_html'],'data-notice="email_verified"')===false,'Repeated simulated validation');global $svc;$next=ex_fixture();$d=$next['definition'];$n=array_values(array_filter($d['nodes'],static function($n){return $n['id']==='E_DUMMY';}))[0];$n['id']='E_NEXT';$n['logical_id']='E_NEXT';$n['position']=1;$n['schedule']['temporal_rule']['duration']['seconds']=10800;$d['nodes'][]=$n;$next=$svc->save($next['id'],$next['revision'],'DUMMY_EXPIRED_NEXT',$d);$r=ex_run($next,array(ex_cmd('ENTER'),ex_cmd('LEAVE'),ex_cmd('ADVANCE',array('seconds'=>10800)),ex_cmd('EMAIL',array('id'=>'MAIL_0'))));ex_assert($r['verified']&&$r['assessment']!==null&&$r['snapshot']['instances'][$r['assessment']['instance']]['definition_id']==='E_NEXT');ex_assert($r['notice']===EIPSI\StudyEngine\Runtime\PublicMessages::text($next['definition'],'email_expired_next'));});
