ex_case('Ordinary answers keep all questions and persist their values until navigation',function(){global $nativeDefinition;$x=ex_fixture();$c=array(ex_cmd('ENTER'));$before=ex_run($x,$c);$q=$nativeDefinition['elements'][0];$c[]=ex_cmd('ANSWER',array('answers'=>array($q['response_key']=>'No desaparecer'),'touched'=>array(),'instance'=>$before['assessment']['instance']));$r=ex_run($x,$c);ex_assert($r['assessment']['instance']===$before['assessment']['instance']);ex_assert($r['assessment']['definition']['elements']===$before['assessment']['definition']['elements']);ex_assert($r['assessment']['session']['answers'][$q['response_key']]==='No desaparecer');});
ex_case('Answering selected randomized questions does not remove them or lose their answers',function(){global $nativeDefinition;$old=$nativeDefinition;try{$nativeDefinition=EIPSI\AssessmentEditor\Definition::validate(json_decode(file_get_contents(__DIR__.'/assessment-editor/randomization-fixture.json'),true));$x=ex_fixture();$c=array(ex_cmd('ENTER'));$before=ex_run($x,$c);$d=EIPSI\AssessmentEditor\Randomization::apply($before['assessment']['definition'],$before['assessment']['session']['randomization']);$answers=array();$walk=function($items)use(&$walk,&$answers){foreach($items as $e){if($e['response_key'])$answers[$e['response_key']]='Respuesta aleatoria';$walk($e['children']);}};$walk($d['elements']);ex_assert(count($answers)>0);$c[]=ex_cmd('ANSWER',array('answers'=>$answers,'touched'=>array(),'instance'=>$before['assessment']['instance']));$after=ex_run($x,$c);$resolved=EIPSI\AssessmentEditor\Randomization::apply($after['assessment']['definition'],$after['assessment']['session']['randomization']);ex_assert($resolved['elements']===$d['elements']);ex_assert($after['assessment']['session']['answers']===$answers);}finally{$nativeDefinition=$old;}});
ex_case('Test 2 shape: required first page plus lazy randomized second page can finish with every visible answer',function(){global $nativeDefinition;$old=$nativeDefinition;try{$r=json_decode(file_get_contents(__DIR__.'/assessment-editor/randomization-fixture.json'),true);$random=$r['elements'][0];$random['properties']['count']=1;$first=$random['children'][0];$first['id']='EL_FIRST';$first['response_key']='R_FIRST';$first['properties']['variable_name']='first_question';$break=json_decode(file_get_contents(__DIR__.'/assessment-editor/functional-fixture.json'),true)['elements'][3];$r['elements']=array($first,$break,$random);$r['flow']['pages']=array();$nativeDefinition=EIPSI\AssessmentEditor\Definition::validate($r);$x=ex_fixture();$c=array(ex_cmd('ENTER'),ex_cmd('NEXT',array('answers'=>array('R_FIRST'=>'Primera completa'),'touched'=>array('R_FIRST'=>true))));$page=ex_run($x,$c);ex_assert($page['assessment']['session']['page']===1);$resolved=EIPSI\AssessmentEditor\Randomization::apply($page['assessment']['definition'],$page['assessment']['session']['randomization']);$a=array('R_FIRST'=>'Primera completa');foreach($resolved['elements'][2]['children'] as $q)$a[$q['response_key']]='Segunda completa';$t=array_fill_keys(array_keys($a),true);$c[]=ex_cmd('SUBMIT',array('answers'=>$a,'touched'=>$t));$done=ex_run($x,$c);ex_assert($done['snapshot']['instances'][$page['assessment']['instance']]['state']==='COMPLETED');}finally{$nativeDefinition=$old;}});
ex_case('Different seeds can produce distinct native outcomes and identical seeds replay identically',function(){global $nativeDefinition,$svc;$old=$nativeDefinition;try{$nativeDefinition=EIPSI\AssessmentEditor\Definition::validate(json_decode(file_get_contents(__DIR__.'/assessment-editor/randomization-fixture.json'),true));$x=ex_fixture();$context=array('created_at'=>'2026-10-13T08:00:00Z','timezone'=>'UTC');$outcomes=array();for($i=1;$i<=12;$i++){$c=$context+array('seed_hex'=>str_pad(dechex($i),64,'0',STR_PAD_LEFT));$a=$svc->experience($x['id'],$c,array(ex_cmd('ENTER')));$b=$svc->experience($x['id'],$c,array(ex_cmd('ENTER')));$draw=$a['assessment']['session']['randomization'];ex_assert($draw===$b['assessment']['session']['randomization']);$outcomes[json_encode(array_column($draw['blocks'],'order'))]=true;}ex_assert(count($outcomes)>1);}finally{$nativeDefinition=$old;}});
ex_case('Direct first assessment does not send a duplicate availability email even under SEND policy',function(){foreach(array('NEVER','AFTER_FIRST') as $mode){$x=ex_fixture($mode);$r=ex_run($x,array(ex_cmd('ENTER')));ex_assert($r['assessment']!==null&&$r['emails']===array());$r=ex_run($x,array(ex_cmd('ENTER'),ex_cmd('LEAVE'),ex_cmd('ADVANCE',array('seconds'=>600))));ex_assert(count($r['emails'])===1&&$r['emails'][0]['purpose']==='ASSESSMENT_REMINDER');}});
ex_case('Immediate V2 skips post-first review; optional review in the other modes precedes completion',function(){global $svc,$nativeDefinition;foreach(array('IMMEDIATE','AFTER_FIRST','NEVER') as $mode){$x=ex_fixture($mode);$c=array(ex_cmd('ENTER'));if($mode==='IMMEDIATE')$c[]=ex_cmd('EMAIL',array('id'=>'MAIL_0'));$a=array();foreach($nativeDefinition['elements'] as $q)$a[$q['response_key']]='Completa';$c[]=ex_cmd('SUBMIT',array('answers'=>$a,'touched'=>array()));$r=ex_run($x,$c);ex_assert($r['completion']!==null&&$r['review']===($mode!=='IMMEDIATE'));$beforeConfirm=$c;if($mode!=='IMMEDIATE'){$c[]=ex_cmd('CONFIRM_EMAIL',array('email'=>'participante@example.test'));$r=ex_run($x,$c);ex_assert(!$r['review']&&$r['completion']!==null);} $d=$x['definition'];$d['protocol_metadata']['longitudinal']['initial_screen']['authentication']['confirm_after_first']=false;$x=$svc->save($x['id'],$x['revision'],'NO_REVIEW_'.$mode,$d);ex_assert(!ex_run($x,$beforeConfirm)['review']);}});
ex_case('Withdrawal completion preserves rich variables and rejects unsafe markup in the real shell and replay',function(){global $svc;$x=ex_fixture('NEVER',0,true);$d=$x['definition'];$d['protocol_metadata']['longitudinal']['initial_screen']['withdrawal']['completion_html']='<h2>Gracias</h2><p><strong>[OPCION]</strong> <em>[CONFIRMACION]</em></p><script>alert(1)</script>';$x=$svc->save($x['id'],$x['revision'],'WITHDRAW_MESSAGE',$d);$w=$x['definition']['protocol_metadata']['longitudinal']['initial_screen']['withdrawal'];$c=array(ex_cmd('ENTER'));$c[]=ex_cmd('WITHDRAW',array('mode'=>'RETAIN_FOR_ANALYSIS','email'=>'participante@example.test','confirmation_text'=>L\InitialScreen::withdrawalPhrase($w,'RETAIN_FOR_ANALYSIS')));$r=ex_run($x,$c);ex_assert(strpos($r['withdrawal_completion_html'],'<strong>'.$w['retain_label'].'</strong>')!==false&&strpos($r['withdrawal_completion_html'],'<script')===false&&$r['withdrawal_html']===null);$html=(new L\EmailTemplate())->screen(array('study'=>$x['definition']['study'],'definition'=>$x['definition'],'shell'=>'WITHDRAWAL_OPTIONS','withdrawal'=>$r['snapshot']['withdrawal'],'view'=>array('revision'=>1),'csrf'=>'DUMMY'));ex_assert(strpos($html,$r['withdrawal_completion_html'])!==false);});
ex_case('First assessment entered by an email link skips email review in both non-immediate modes',function(){global $nativeDefinition;foreach(array('NEVER','AFTER_FIRST') as $mode){$x=ex_fixture($mode,3600);$c=array(ex_cmd('ENTER'),ex_cmd('ADVANCE',array('seconds'=>3600)));$r=ex_run($x,$c);$c[]=ex_cmd('EMAIL',array('id'=>$r['emails'][count($r['emails'])-1]['id']));$a=array();foreach($nativeDefinition['elements'] as $q)$a[$q['response_key']]='Respuesta validada';$c[]=ex_cmd('SUBMIT',array('answers'=>$a,'touched'=>array()));$r=ex_run($x,$c);ex_assert($r['verified']&&!$r['review']&&$r['completion']!==null);}});
ex_case('Dummy review uses the real empty field and rejects an unacknowledged address change',function(){global $nativeDefinition,$svc;$x=ex_fixture();$a=array();foreach($nativeDefinition['elements'] as $q)$a[$q['response_key']]='Respuesta';$c=array(ex_cmd('ENTER'),ex_cmd('SUBMIT',array('answers'=>$a,'touched'=>array())));$r=ex_run($x,$c);ex_assert(strpos($r['review_html'],'id="confirm-study-email" name="email" type="email" value=""')!==false&&strpos($r['review_html'],'data-previous-email=')!==false);$unconfirmed=array('kind'=>'CONFIRM_EMAIL','data'=>array('email'=>'changed@example.test'));ex_reject(function()use($x,$c,$unconfirmed){ex_run($x,array_merge($c,array($unconfirmed)));},'EMAIL_CHANGE_CONFIRMATION_REQUIRED');$c[]=ex_cmd('CONFIRM_EMAIL',array('email'=>'changed@example.test'));$r=ex_run($x,$c);ex_assert($r['email']==='changed@example.test'&&!$r['review']);});
