ex_case('Repeat eligibility and actual new attempt follow the scheduled opportunity policy',function(){global $svc,$nativeDefinition;foreach(array(true,false) as $unique){$x=ex_fixture();$d=$x['definition'];foreach($d['nodes'] as &$n)if($n['id']==='E_DUMMY')$n['metadata']['scheduled_interaction']['unique_response']=$unique;unset($n);$x=$svc->save($x['id'],$x['revision'],'REPEAT_POLICY',$d);$answers=array();foreach($nativeDefinition['elements'] as $q)$answers[$q['response_key']]='Primera';$c=array(ex_cmd('ENTER'),ex_cmd('SUBMIT',array('answers'=>$answers,'touched'=>array())),ex_cmd('CONFIRM_EMAIL',array('email'=>'participante@example.test')));$done=ex_run($x,$c);ex_assert($done['completion_can_repeat']===!$unique);if($unique){ex_reject(function()use($x,$c){ex_run($x,array_merge($c,array(ex_cmd('REPEAT'))));},'PREVIEW_REPEAT_UNAVAILABLE');continue;}$c[]=ex_cmd('REPEAT');$again=ex_run($x,$c);ex_assert($again['assessment']!==null&&$again['assessment']['session']['answers']===array()&&$again['completion']===null);$id=$again['assessment']['instance'];$c[]=ex_cmd('SUBMIT',array('answers'=>$answers,'touched'=>array(),'instance'=>$id));$second=ex_run($x,$c);ex_assert($second['completion']!==null&&$second['snapshot']['instances'][$id]['state']==='COMPLETED');$c[]=ex_cmd('ADVANCE',array('seconds'=>7201));ex_assert(!ex_run($x,$c)['completion_can_repeat']);ex_reject(function()use($x,$c){ex_run($x,array_merge($c,array(ex_cmd('REPEAT'))));},'PREVIEW_REPEAT_UNAVAILABLE');}});
